"""New-condition boundary controls on generated bytes, not neural-data results.

Original-material admission is stubbed only for the small view/ordering fixtures;
the production API still invokes the unchanged authenticated original admission.
No participant process, model, original dataset or protected target is used.
"""
import copy
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import tempfile
import types
import unittest
from unittest import mock

HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('smc_full_panel_under_test', HERE / 'benchmark.py')
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)


def dump(path, value):
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + '\n')
    return hashlib.sha256(path.read_bytes()).hexdigest()


class FullPanelControls(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        # Source-only context is supplied by the single selected operator campaign.
        cls.repository = Path(os.environ.get('SMC_FULL_PANEL_REPOSITORY_ROOT', str(HERE.parents[4])))
        cls.contract = Path(os.environ.get('SMC_FULL_PANEL_CONTRACT_ROOT', str(HERE)))
        cls.bound = module.FullPanelAPI(cls.repository, cls.contract)

    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix='smc-full-panel-control-')
        self.root = Path(self.temporary.name)
        self.api = copy.copy(self.bound)
        self.pair_root = self.root / 'pair'
        self.pair_root.mkdir()
        self.condition = module.CONDITIONS[0]
        rows = {}
        for condition in module.CONDITIONS:
            base = self.pair_root / condition
            base.mkdir()
            contents = {
                'paper.pdf': b'generated paper fixture',
                'inputs/mc_maze/test/train_input_20ms.h5': b'generated training',
                module.TEST_INPUT: b'generated unlabelled TEST held-in',
                'inputs/mc_maze/val/train_input_20ms.h5': b'generated train',
                'inputs/mc_maze/val/eval_input_20ms.h5': b'generated validation input',
                'inputs/mc_maze/val/eval_target_20ms.h5': b'generated validation target',
            }
            inventory = []
            for name, body in contents.items():
                path = base / name
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(body)
                inventory.append({'path': name, 'bytes': len(body), 'sha256': hashlib.sha256(body).hexdigest()})
            manifest = {'files': sorted(inventory, key=lambda row: row['path'])}
            rows[condition] = dump(base / 'delivery_manifest.json', manifest)
        self.pair = self.pair_root / 'pair_manifest.json'
        self.pair_doc = {'condition_manifest_sha256': rows}
        self.pair_sha = dump(self.pair, self.pair_doc)
        self.admission = {'pair': self.pair_doc, 'panels': {key: {} for key in module.CONDITIONS},
                          'policy': self.api.load_policy()}
        self.api.inspect_pair = mock.Mock(return_value=self.admission)
        self.task = self.contract / 'task.json'
        self.program = self.root / 'candidate.py'
        self.program.write_text('# generated source fixture; never executed\n')
        self.program_sha = hashlib.sha256(self.program.read_bytes()).hexdigest()
        self.plan = self.method_plan()
        self.plan_path = self.root / 'plan.json'
        dump(self.plan_path, self.plan)
        self.cap = 1024 * 1024

    def tearDown(self):
        self.temporary.cleanup()

    def method_plan(self, condition=None):
        condition = condition or self.condition
        actions = []
        if condition == module.CONDITIONS[1]:
            actions = [dict(path=row['path'], sha256=row['sha256'],
                            **{flag: False for flag in module.ACTION_FLAGS})
                       for row in self.api.base.asset_allowlist()['files']]
        return {'schema': 'smc_full_panel_method_plan_v1', 'role': 'participant',
            'method_id': 'generated-control', 'condition': condition,
            'inference_condition_id': module.INFERENCE_CONDITION, 'source_sha256': self.program_sha,
            'seed': 17, 'adaptation_procedure': 'Compute permitted cross-trial held-in sufficient statistics; optional declared parameter updates.',
            'parameter_adaptation_planned': True, 'behavior_guided_fitting_planned': False,
            'behavior_guided_selection_planned': True, 'planned_asset_actions': actions}

    def development(self):
        output = self.root / 'development'
        self.api.prepare_development_view(self.pair, self.pair_sha, self.task, module.TASK_SHA256,
            self.condition, output, max_bytes=self.cap)
        manifest = output / 'development_manifest.json'
        return manifest, self.api.hash_file(manifest)

    def method(self, artifacts=None):
        dev, dev_sha = self.development()
        path = self.root / 'method.json'
        self.api.freeze_method(dev, dev_sha, self.pair, self.pair_sha, self.task, module.TASK_SHA256,
            self.condition, self.program, self.plan_path, artifacts or {}, path, max_bytes=self.cap)
        return path, self.api.hash_file(path)

    def inspect_method(self, path, sha):
        return self.api.inspect_method(path, sha, self.pair, self.pair_sha, self.task,
            module.TASK_SHA256, self.condition, max_bytes=self.cap)

    def actual(self, method_sha):
        return {'schema': 'smc_full_panel_actual_use_v1', 'role': 'participant',
            'method_id': self.plan['method_id'], 'condition': self.condition,
            'inference_condition_id': module.INFERENCE_CONDITION,
            'source_sha256': self.program_sha, 'seed': 17, 'method_freeze_sha256': method_sha,
            'parameter_adaptation_performed': True,
            'actual_adaptation_description': 'Declared full-panel parameter/statistic update; declaration is not execution proof.',
            'behavior_guided_fitting': False, 'behavior_guided_selection': False, 'asset_usage': []}

    def test_authentic_parent_task_and_selected_budget(self):
        self.assertEqual(len(module.PARENT_TASK_SHA256), 64)
        self.assertEqual(self.api.hash_file(self.repository / module.TASK_RELATIVE), module.PARENT_TASK_SHA256)
        policy = self.api.load_policy()
        budget = {'improvement': {key: policy['resource_profile'][key]
                  for key in ('cpu_seconds', 'wall_seconds', 'memory_bytes', 'threads')}}
        self.assertEqual(self.api.validate_budget(budget), budget)
        for key in budget['improvement']:
            changed = copy.deepcopy(budget)
            changed['improvement'][key] += 1
            with self.subTest(key=key), self.assertRaises(ValueError):
                self.api.validate_budget(changed)
        with self.assertRaises(ValueError):
            self.api.validate_budget({'reproduction': budget['improvement'], **budget})

    def test_stale_v2_pair_is_rejected_before_material_admission(self):
        stale = self.root / 'pair_manifest.json'
        sha = dump(stale, {'schema': 'smc_continuous_pair_v2', 'resource_budget': {}})
        with self.assertRaisesRegex(ValueError, 'stale or wrong'):
            module.FullPanelAPI.inspect_pair(self.api, stale, sha, self.task, module.TASK_SHA256,
                                             max_bytes=self.cap)

    def test_fresh_plan_reuses_admission_but_rebuilds_condition_identity(self):
        admitted = {}
        panel = {'expected_shapes': {key: [1, 2, 3] for key in
                 set(self.api.source.REQUIRED_KEYS) | set(self.api.source.OPTIONAL_KEYS)}}
        for condition in module.CONDITIONS:
            for name, content in {
                'registered_task.json': {'old_task': True},
                'measurement_policy.json': {'old_policy': True},
                'resource_budget.json': {'old_budget': True},
                'task.json': {'old_instructions': True},
                'delivery_manifest.json': {'old_manifest': True},
                'inputs/mc_maze/test/panel.json': panel,
                'attribution.json': {'generated_fixture': True},
            }.items():
                self.api.retained.plan_json(admitted, condition + '/' + name, content)
        self.api.retained.plan_json(admitted, 'pair_manifest.json', {'schema': 'old_v2_fixture'})
        profile = {key: self.api.load_policy()['resource_profile'][key]
                   for key in ('cpu_seconds', 'wall_seconds', 'memory_bytes', 'threads')}
        budget = {'improvement': profile}
        with mock.patch.object(self.api.base, '_plan', return_value=({}, admitted)) as admission:
            pair, plan = self.api._plan(self.root, self.root, self.program, self.task,
                module.TASK_SHA256, budget, self.cap)
        self.assertEqual(admission.call_args.args[4], module.PARENT_TASK_SHA256)
        self.assertEqual(set(admission.call_args.args[5]), {'reproduction', 'improvement'})
        self.assertEqual(pair['schema'], 'smc_full_panel_pair_v1')
        self.assertEqual(pair['resource_budget'], budget)
        self.assertEqual(pair['current_task_sha256'], module.TASK_SHA256)
        for condition in module.CONDITIONS:
            prefix = condition + '/'
            self.assertEqual(plan[prefix + 'registered_task.json']['sha256'], module.TASK_SHA256)
            self.assertEqual(plan[prefix + 'measurement_policy.json']['sha256'], module.POLICY_SHA256)
            instructions = json.loads(plan[prefix + 'task.json']['content'])
            self.assertEqual(instructions['outcome'], 'improvement')
            self.assertEqual(instructions['inference_condition_id'], module.INFERENCE_CONDITION)
            self.assertEqual(json.loads(plan[prefix + 'resource_budget.json']['content']), budget)
            manifest_row = plan[prefix + 'delivery_manifest.json']
            manifest = json.loads(manifest_row['content'])
            self.assertEqual(manifest['schema'], 'smc_full_panel_delivery_v1')
            self.assertEqual(manifest['condition'], condition)
            self.assertEqual(manifest['inference_condition_id'], module.INFERENCE_CONDITION)
            self.assertEqual(manifest['current_task_sha256'], module.TASK_SHA256)
            self.assertEqual(manifest['policy_sha256'], module.POLICY_SHA256)
            self.assertEqual(pair['condition_manifest_sha256'][condition],
                             hashlib.sha256(manifest_row['content']).hexdigest())

    def test_output_refusal_does_not_create_directories(self):
        protected = self.root / 'protected'
        protected.mkdir()
        repo = self.root / 'pretend-checkout'
        repo.mkdir()
        (repo / '.git').mkdir()
        for output in (protected / 'out', protected / 'missing' / 'out',
                       repo / 'out', repo / 'missing' / 'out'):
            with self.subTest(output=output), self.assertRaises((ValueError, FileNotFoundError)):
                self.api._outside(output, protected)
            self.assertFalse(output.exists())
            self.assertFalse(output.parent.name == 'missing' and output.parent.exists())

    def test_development_preserves_validation_and_excludes_test_input(self):
        path, sha = self.development()
        view = path.parent
        self.assertFalse((view / module.TEST_INPUT).exists())
        self.assertTrue((view / 'inputs/mc_maze/val/eval_input_20ms.h5').is_file())
        self.assertTrue((view / 'inputs/mc_maze/val/eval_target_20ms.h5').is_file())
        record = self.api.inspect_development_view(path, sha, self.pair, self.pair_sha, self.task,
            module.TASK_SHA256, self.condition, max_bytes=self.cap)
        self.assertFalse(record['earlier_authoring_blindness_verified'])
        extra = view / module.TEST_INPUT
        extra.write_bytes(b'forbidden generated test input')
        with self.assertRaises(ValueError):
            self.api.inspect_development_view(path, sha, self.pair, self.pair_sha, self.task,
                module.TASK_SHA256, self.condition, max_bytes=self.cap)

    def test_rehashed_development_manifest_cannot_admit_test_input(self):
        path, _ = self.development()
        record = json.loads(path.read_text())
        target = path.parent / module.TEST_INPUT
        target.write_bytes(b'test')
        record['files'].append({'path': module.TEST_INPUT, 'bytes': 4, 'sha256': hashlib.sha256(b'test').hexdigest()})
        path.chmod(0o600)
        sha = dump(path, record)
        with self.assertRaisesRegex(ValueError, 'TEST-input-excluding'):
            self.api.inspect_development_view(path, sha, self.pair, self.pair_sha, self.task,
                module.TASK_SHA256, self.condition, max_bytes=self.cap)

    def test_method_snapshots_program_and_refuses_later_snapshot_mutation(self):
        path, sha = self.method()
        record = self.inspect_method(path, sha)
        self.program.write_text('# changed external source after freeze\n')
        self.inspect_method(path, sha)  # Immutable selected snapshot remains unchanged.
        frozen = Path(record['program']['path'])
        frozen.chmod(0o600)
        frozen.write_text('# changed frozen source\n')
        with self.assertRaises(ValueError):
            self.inspect_method(path, sha)

    def test_candidate_artifact_requires_admitted_development_origin(self):
        dev, dev_sha = self.development()
        artifact = self.root / 'candidate-parameters.bin'
        artifact.write_bytes(b'generated candidate-derived parameters')
        method = self.root / 'method.json'
        with self.assertRaises(ValueError):
            self.api.freeze_method(dev, dev_sha, self.pair, self.pair_sha, self.task, module.TASK_SHA256,
                self.condition, self.program, self.plan_path, {'weights.bin': {'path': str(artifact),
                    'development_manifest_sha256': '0' * 64, 'derivation': 'External unknown data.'}}, method,
                max_bytes=self.cap)
        record = self.api.freeze_method(dev, dev_sha, self.pair, self.pair_sha, self.task, module.TASK_SHA256,
            self.condition, self.program, self.plan_path, {'weights.bin': {'path': str(artifact),
                'development_manifest_sha256': dev_sha, 'derivation': 'Generated fixture derived from admitted training view.'}},
            method, max_bytes=self.cap)
        self.assertFalse(record['candidate_artifact_provenance']['weights.bin']['derivation_verified'])
        self.inspect_method(method, self.api.hash_file(method))

    def test_release_requires_frozen_method_and_delivers_complete_permitted_panel(self):
        output = self.root / 'inference'
        with self.assertRaises(FileNotFoundError):
            self.api.release_inference_view(self.root / 'absent.json', '0' * 64, self.pair, self.pair_sha,
                self.task, module.TASK_SHA256, self.condition, output, max_bytes=self.cap)
        self.assertFalse(output.exists())
        path, sha = self.method()
        record = self.api.release_inference_view(path, sha, self.pair, self.pair_sha,
            self.task, module.TASK_SHA256, self.condition, output, max_bytes=self.cap)
        self.assertTrue((output / module.TEST_INPUT).is_file())
        self.assertTrue(record['release_after_method_freeze'])
        self.assertFalse(record['earlier_authoring_blindness_verified'])
        manifest = output / 'inference_manifest.json'
        self.api.inspect_release(manifest, self.api.hash_file(manifest), path, sha, self.pair, self.pair_sha,
            self.task, module.TASK_SHA256, self.condition, max_bytes=self.cap)
        (output / 'forbidden_target.h5').write_bytes(b'generated extra')
        with self.assertRaises(ValueError):
            self.api.inspect_release(manifest, self.api.hash_file(manifest), path, sha, self.pair, self.pair_sha,
                self.task, module.TASK_SHA256, self.condition, max_bytes=self.cap)

    def test_mutation_during_release_copy_refuses_publication(self):
        path, sha = self.method()
        method = self.inspect_method(path, sha)
        frozen = Path(method['program']['path'])
        original = self.api.io._snapshot
        changed = False
        def snapshot(*args, **kwargs):
            nonlocal changed
            result = original(*args, **kwargs)
            if not changed:
                changed = True
                frozen.chmod(0o600)
                frozen.write_bytes(b'changed while inference view staged')
            return result
        output = self.root / 'inference'
        with mock.patch.object(self.api.io, '_snapshot', side_effect=snapshot), self.assertRaises(ValueError):
            self.api.release_inference_view(path, sha, self.pair, self.pair_sha, self.task,
                module.TASK_SHA256, self.condition, output, max_bytes=self.cap)
        self.assertFalse(output.exists())

    def test_actual_adaptation_is_separate_from_fixed_program(self):
        path, sha = self.method()
        record = self.inspect_method(path, sha)
        actual = self.actual(sha)
        self.assertTrue(self.api.validate_actual(actual, self.condition, record, sha)['parameter_adaptation_performed'])
        actual['parameter_adaptation_performed'] = False
        actual['actual_adaptation_description'] = 'Used cross-trial statistics without changing learned parameters.'
        self.api.validate_actual(actual, self.condition, record, sha)
        changed = copy.deepcopy(record)
        changed['plan']['parameter_adaptation_planned'] = False
        actual['parameter_adaptation_performed'] = True
        with self.assertRaises(ValueError):
            self.api.validate_actual(actual, self.condition, changed, sha)

    def test_missing_or_changed_method_and_plan_fields_are_rejected(self):
        plan = copy.deepcopy(self.plan)
        del plan['adaptation_procedure']
        with self.assertRaises(ValueError):
            self.api.validate_plan(plan, self.condition)
        plan = copy.deepcopy(self.plan)
        plan['parameter_adaptation_planned'] = 1
        with self.assertRaises(ValueError):
            self.api.validate_plan(plan, self.condition)
        path, sha = self.method()
        method = self.inspect_method(path, sha)
        actual = self.actual(sha)
        actual['source_sha256'] = '0' * 64
        with self.assertRaises(ValueError):
            self.api.validate_actual(actual, self.condition, method, sha)

    def test_asset_actual_use_cannot_exceed_plan(self):
        condition = module.CONDITIONS[1]
        plan = self.method_plan(condition)
        self.api.validate_plan(plan, condition)
        actual = self.actual('a' * 64)
        actual['condition'] = condition
        actual['asset_usage'] = [{'path': row['path'], 'sha256': row['sha256'],
            **{flag: False for flag in module.ACTION_FLAGS.values()}} for row in plan['planned_asset_actions']]
        actual['asset_usage'][0]['loaded'] = True
        with self.assertRaises(ValueError):
            self.api.validate_actual(actual, condition, {'plan': plan}, 'a' * 64)
        plan['planned_asset_actions'][0]['load'] = True
        self.api.validate_actual(actual, condition, {'plan': plan}, 'a' * 64)

    def test_comparison_preserves_all_four_metrics_and_references(self):
        metrics = {'offline': {'co-bps': 0.4, 'vel R2': 0.8, 'psth R2': 0.5, 'fp-bps': 0.2}}
        report = self.api.compare_metrics(metrics)
        self.assertEqual(report['metrics'], metrics)
        self.assertEqual(len(report['comparisons']), 6)
        self.assertEqual(report['policy_sha256'], module.POLICY_SHA256)
        self.assertEqual(report['inference_condition_id'], module.INFERENCE_CONDITION)
        self.assertFalse(report['inductive_generalization_established'])
        self.assertEqual(report['binary_decision'], 'not_applicable')
        metrics['offline'].pop('fp-bps')
        with self.assertRaises(ValueError):
            self.api.compare_metrics(metrics)


if __name__ == '__main__':
    unittest.main()
